     1→import * as React from "react";
     2→import { Input } from "../ui/input";
     3→import { cn } from "../../lib/utils";
     4→
     5→export interface QuantityInputProps extends Omit<React.ComponentPropsWithoutRef<typeof Input>, "type" | "inputMode"> {
     6→  maxDecimalPlaces?: number;
     7→  allowNegative?: boolean;
     8→}
     9→
    10→const QuantityInput = React.forwardRef<HTMLInputElement, QuantityInputProps>(
    11→  ({ className, maxDecimalPlaces = 8, allowNegative = false, value, defaultValue, onChange, ...props }, ref) => {
    12→    // Modify the sanitizedValue logic to consider defaultValue
    13→    const sanitizedValue =
    14→      value !== null && value !== undefined
    15→        ? value
    16→        : defaultValue !== null && defaultValue !== undefined
    17→          ? defaultValue
    18→          : "";
    19→
    20→    const handleChange = React.useCallback(
    21→      (e: React.ChangeEvent<HTMLInputElement>) => {
    22→        // Allow negative sign only at the start if allowNegative is true
    23→        const regex = allowNegative ? /^-?\d*\.?\d*$/ : /^\d*\.?\d*$/;
    24→        const rawValue = e.target.value;
    25→
    26→        // Return if the input doesn't match our regex pattern
    27→        if (!regex.test(rawValue)) {
    28→          return;
    29→        }
    30→
    31→        // Ensure only one decimal point
    32→        const decimalIndex = rawValue.indexOf(".");
    33→        let processedValue = rawValue;
    34→        if (decimalIndex !== -1) {
    35→          processedValue = rawValue.slice(0, decimalIndex + 1) + rawValue.slice(decimalIndex + 1).replace(/\./g, "");
    36→        }
    37→
    38→        // Limit decimal places
    39→        if (decimalIndex !== -1) {
    40→          const decimalPart = processedValue.slice(decimalIndex + 1);
    41→          if (decimalPart.length > maxDecimalPlaces) {
    42→            processedValue = processedValue.slice(0, decimalIndex + maxDecimalPlaces + 1);
    43→          }
    44→        }
    45→
    46→        // Call the original onChange with the processed value
    47→        if (onChange) {
    48→          const syntheticEvent = {
    49→            ...e,
    50→            target: {
    51→              ...e.target,
    52→              value: processedValue,
    53→            },
    54→          };
    55→          onChange(syntheticEvent as React.ChangeEvent<HTMLInputElement>);
    56→        }
    57→      },
    58→      [maxDecimalPlaces, allowNegative, onChange],
    59→    );
    60→
    61→    return (
    62→      <Input
    63→        type="text"
    64→        inputMode="decimal"
    65→        placeholder="0.00"
    66→        className={cn("text-right", className)}
    67→        ref={ref}
    68→        {...props}
    69→        value={sanitizedValue}
    70→        onChange={handleChange}
    71→      />
    72→    );
    73→  },
    74→);
    75→
    76→QuantityInput.displayName = "QuantityInput";
    77→
    78→export { QuantityInput };
    79→

